  tests: [["cuadrados pares", "assert cuadrados_pares([1,2,3,4]) == [4,16]"], ["índice", "assert indice_invertido(['a','b','a']) == {'a':[0,2],'b':[1]}"]],
  extra: [["lista vacía", "assert indice_invertido([]) == {} and cuadrados_pares([]) == []"]],
