  solution: "from collections import defaultdict\n\ndef cuadrados_pares(xs: list[int]) -> list[int]:\n    return [x * x for x in xs if x % 2 == 0]\n\ndef indice_invertido(palabras: list[str]) -> dict[str, list[int]]:\n    idx = defaultdict(list)\n    for i, w in enumerate(palabras):\n        idx[w].append(i)\n    return dict(idx)\n",
